Assume $\>\alpha^N(0)$ converges weakly, as $N\to\infty$, to some fixed distribution 
 $\>\alpha_0\in \Lambda$. Then  the empirical measure  
$\>\alpha^N(t)$ converges  in distribution to a deterministic dynamical system denoted by $\>\alpha(t)$, which  satisfies  the  
following infinite system of nonlinear forward Kolmogorov's equations
\begin{align} \label{eq:kolmo1}
 \frac{d\alpha_{j,k}(t)}{dt}+\left[\lambda b(t)+\mu j +\lambda \1_{\{k>0\}}\right]\alpha_{j,k}(t) & = \nonumber \\ 
 \lambda b(t)\alpha_{j-1,k}(t)\1_{\{j>0\}} 
+\mu(j+1)\alpha_{j+1,k-1}(t)\1_{\{k>0\}} &+\lambda \alpha_{j,k+1}(t), \quad (j,k) \in \mathbb{N}^2, \ t\ge0,
\end{align}
 where $\>\alpha(t)\in \Lambda$, $\>\alpha(0)= \>\alpha_0$ and $\displaystyle b(t) \stackrel{\mbox{\tiny def}}{=} 1-\sum_{j\in\mathbb{N}} \alpha_{j,0}(t)$.

\label{thm:S1}
\begin{enumerate}\mbox{ } 
\item For each $t\ge0$ there exists a unique distribution $\>\alpha(t)$ satisfying the nonlinear system~\eqref{eq:kolmo1}. In addition, for any $\lambda,\mu>0$, as $t\to\infty$, the distribution
$\>\alpha(t)$ converges in ~$\Lambda$ (defined by~\eqref{eq:Lambda})  to the unique equilibrium point $\>\pi >\>0$ given by 
    \begin{equation}\label{eq:invar2}
        \pi_{j,k}=e^{-\rho\beta} \frac{(\rho\beta)^j}{j!}(1-\beta)\beta^k, \quad \forall j,k\in \mathbb{N},
    \end{equation}
    where
    \begin{equation}\label{eq:param}
     \rho\stackrel{\mbox{\tiny def}}{=}\frac{\lambda}{\mu}, \ \mathrm{and} \ 
     \beta\stackrel{\mbox{\tiny def}}{=} \lim_{t\to\infty}b(t) = 
     \frac{U+\rho+1-\sqrt{(U+\rho+1)^2-4\rho U}}{2\rho} < 1,
    \end{equation}
  $\displaystyle U= \lim_{N\to\infty}M_N/N$  being the constant introduced in Section~\ref{sec:intro}.
\item  There is a mass conservation of the form 
\begin{equation}\label{eq:mass2}
U=\sum_{j,k\geqslant 0} (j+k)\alpha_{j,k}(t), \quad 0\le t\le\infty,
    \end{equation}
  which, although somehow surprising, follows implicitly from the  functional equation~\eqref{eq:S2}. 

\item Assuming at $t=0$ all particles are reserved parking spaces, i.e. 
$\>\alpha(0)$ has its support in $\mathbb{N}\times \{0\}$, then, as $t\to\infty$,
\begin{equation}\label{eq:vt1}
    b(t) = \beta + \mathcal{O}(e^{-vt}), 
   \end{equation}
 where
 \begin{equation}\label{eq:vt2}
 v = \min[ \mu, \lambda\bigl(\sqrt{1}-\sqrt{\beta}\bigr)^2],
 \end{equation}
 and $1/v$ being viewed as the relaxation time of the system.
 \end{enumerate}

The rate function $\delta(t)$ satisfies the differential system  
\begin{equation}\label{eq:sys}
\begin{cases}
    \displaystyle \frac{d \delta(t)}{dt} + \mu \delta(t)& = \lambda\mu(1-H(t)), \quad \delta(0)=0, 
    \\[0.3cm]
     H(t) & =  \psi_\delta(t)+\lambda \int_0^t D(s,t)H(s) ds.
\end{cases}
\end{equation}

\label{lem:dlimit}
The integro-differential system~\eqref{eq:sys} has a unique solution 
$\delta(\cdot)$ with
\begin{equation}\label{eq:dlimit}
    \delta(0)= 0, \quad\mathrm{and} \quad \delta \stackrel{\mbox{\tiny def}}{=} \lim_{t\to\infty}\delta(t)
\end{equation}
exists and is a finite positive constant.

\label{lem:pform} Any \emph{reachable} stationary distribution
of the tandem driven by equation~\eqref{eq:S2} has a product form $F(x,y)\displaystyle \stackrel{\mbox{\tiny def}}{=}\lim_{t\to\infty} F(x,y,t)$ in the sense that 
\begin{equation}\label{eq:pform}
F(x,y) = e^{p(x-1)}\,\frac{1-q}{1-qy},
\end{equation}

Letting $t\to\infty$ in \eqref{eq:S2}, we obtain the following stationary Kolmogorov's equations of a \emph{quasi-reversible} system, which, after setting 
  $F(x,y)\stackrel{\mbox{\tiny def}}{=} F(x,y,\infty)$, have the form
\begin{equation}\label{eq:stat}
\left(\delta (1-x) + \lambda \biggl(1-\frac{1}{y}\biggr)\right) F(x,y) = \mu(y-x)\frac{\partial F(x,y)}{\partial x} + 
\lambda \biggl(1-\frac{1}{y}\biggr)F(x,0).
\end{equation}
  Then, inserting \eqref{eq:pform} into~\eqref{eq:stat},
we obtain immediately the necessary relations
\begin{equation}\label{eq:stat1}
\delta = \mu p = \lambda q = \lambda(1-F(1,0)),
\end{equation}
and the proof of Lemma~\ref{lem:pform} is concluded.

\label{lem:HS}
 Let $f(\cdot)$ be an integrable function of $t$ on 
 $\mathbb{R}_+$, such that 
 $\displaystyle l=\lim_{t\to\infty}f(t)$ exists. Then 
\begin{equation}\label{eq:conv}
\lim_{t\to\infty}\int_0^t \mu e^{\mu(s-t)} f(s)ds = l.
\end{equation}

System~\eqref{eq:kolmo2}  rewrites in the matrix form
\begin{equation}\label{eq:mat2}
  \frac{d\>\alpha(t)}{dt} = \>\alpha(t)M(a(t)),
 \end{equation}
  where $\>\alpha(t)$ is a row vector and $M(a(t))$ a tridiagonal matrix,  denoted in this way to emphasize the dependence on $a(t)$. Now we introduce the  iterative vector scheme
\begin{equation}\label{eq:scheme3}
  \begin{cases}
      a_0(t) =  \>\alpha_0(t) =0,  \quad t\ge 0, \\[0.1cm]
     \displaystyle a_n(t) = \sum_{j=0}^K j\alpha_{n,j}(t), \\[0.4cm]
     \>\alpha_{n+1}(0) =\>\alpha(0), \\[0.2cm]
    \displaystyle \frac{d\>\alpha_{n+1}(t)}{dt} = \>\alpha_{n+1}(t)M(a_n(t)), \quad n\ge0,  
  \end{cases} 
  \end{equation}
 which can be shown, using Appendix~\ref{sec:A1}, to be increasing in the sense that $a_n(t)<a_{n+1}(t)<U$.

\label{thm:S3}
For each $t\ge0$ there exists a unique distribution $\>\alpha(t)$ satisfying the nonlinear system~\eqref{eq:kolmo2}. In addition, for any $\lambda,\mu>0$, there is a unique equilibrium point
$\displaystyle\lim_{t\to\infty}\>\alpha(t)=\>\pi >\>0$ given by 
\begin{align} \label{eq:invar3}
\pi_{jk} = \frac{1}{Z}\frac{\rho_R^j}{j!}{\rho_V^{k}}, \quad 0\le j+k\le K,
\end{align}
where $Z$ is a normalizing constant and $(\rho_R,\rho_V)$ is obtained as the unique solution of the  system 
\begin{equation}\label{eq:toto}
\begin{cases}
\rho_R &=\displaystyle\frac{\lambda}{\mu}\biggl( 1-\displaystyle\sum_{j=0}^K\pi_{j0}\biggr),\\[0.4cm]
U&= \displaystyle\sum_{j,k} (j+k)\pi_{jk}.
\end{cases}
\end{equation}

\label{lem:pform3} Any \emph{reachable} stationary distribution
of the tandem driven by equation~\eqref{eq:S3} has the generating function $F(x,y)\displaystyle \stackrel{\mbox{\tiny def}}{=}\lim_{t\to\infty} F(x,y,t)$, 
\begin{equation}\label{eq:pform3}
F(x,y) = \dfrac{1}{Z}\sum_{j+k\leqslant K} \frac{(px)^j}{j!}\,(qy)^k,
\end{equation}
where $\displaystyle Z=\sum_{j+k\leqslant K} \frac{p^j}{j!}\,q^k$ is the normalizing constant and where  $p>0$ and $0\le q<1$ are uniquely determined by $\mu p = \lambda  d$ with 
$\displaystyle d= 1-Z^{-1}\sum_{j=0}^K p^j/j!$,
and by the mass conservation equation 
\begin{align}\label{eq:mass3}
    U=\dfrac{1}{Z}\sum_{j+k\leqslant K} (j+k)\frac{p^j q^k}{j!}.
\end{align}

Letting $t\to\infty$ in equation~\eqref{eq:S3}, we obtain the following stationary Kolmogorov's equations of a \emph{quasi-reversible} system, which, after setting 
  $F(x,y)\stackrel{\mbox{\tiny def}}{=} F(x,y,\infty)$, have the form
\begin{align}\label{eq:stat3}
&\left(\lambda d(1-x) + \lambda c\biggl(1-\frac{1}{y}\biggr)\right) F(x,y) \nonumber\\
&= \mu(y-x) \frac{\partial F(x,y)}{\partial x} + 
\lambda c \biggl(1-\frac{1}{y}\biggr)F(x,0)+\lambda d(1-x)F_K(x,y),
\end{align}
where $c=c(\infty)$ and $d=d(\infty)$.


  Then, inserting \eqref{eq:pform3} into~\eqref{eq:stat3}, we obtain  (after some easy algebra) the necessary relation 
\begin{equation*}
  \mu p = \lambda d,
\end{equation*}
which, combined with the mass conservation~\eqref{eq:mass3}, yields a system of two equations  with two unknowns $p$ and $q$, having a unique solution (see~\cite[Theorem 3]{fricker2022mean} for details). The proof of Lemma~\ref{lem:pform3} is concluded.
